// ── Stateless helpers (no runtime needed) ────────────────────────────────────
//
// `#[frb(sync)]`: pure, microsecond-scale, and called from build methods, so
// paying a Dart `Future` round-trip for them would be silly. Nothing here
// touches the runtime lock, so blocking the isolate thread is free.

/// The comrade_jni crate version (e.g. "0.1.0").
#[frb(sync)]
pub fn version() -> String {
    crate::version()
}

/// A freshly generated secp256k1 keypair, Bech32-encoded. Standalone — doesn't
/// touch the encrypted store; see [`generate_identity`] and [`unlock_vault`]
/// for the store-backed identity flow every UI screen actually drives.
#[frb(sync)]
pub fn generate_keypair() -> Result<KeypairDto, UiError> {
    crate::generate_keypair()
}

/// Derive the npub from an nsec Bech32 string, or `None` if it doesn't parse.
#[frb(sync)]
pub fn npub_from_nsec(nsec: String) -> Option<String> {
    crate::npub_from_nsec(nsec)
}

/// The display label for a workspace discriminant, or `None` for an unknown key.
#[frb(sync)]
pub fn workspace_label(workspace: String) -> Option<String> {
    crate::workspace_label(workspace)
}

/// Every workspace discriminant and its label — a stable, store-free list
/// (contrast [`workspaces`], which also reports which one is active).
#[frb(sync)]
pub fn all_workspaces() -> Vec<WorkspaceKeyLabel> {
    crate::all_workspaces()
}

// ── Runtime lifecycle ────────────────────────────────────────────────────────

/// Materialise the process-global runtime, if some other caller (e.g. Kotlin
/// constructing `Comrade()`) has not already. The Dart counterpart of
/// `Comrade()`; there is no handle to hold onto because there is nothing to
/// hold — every function below finds the same runtime on its own.
pub fn init_runtime() {
    let _ = runtime();
}

/// [`init_runtime`], but seeding the runtime with an explicit relay set —
/// AUDIT.md COMMS-03's isolated-relay test hook. Only takes effect if this is
/// what first creates the runtime; the shipping app calls [`init_runtime`].
pub fn init_runtime_with_relays(relays: Vec<String>) {
    let _ = crate::global_runtime_with_relays(relays);
}

/// Open the encrypted store, restore or seed the identity, build the engines,
/// and start the background feed/DM loops. Safe to call more than once
/// (returns the already-loaded identity) — including when the *other* ABI
/// already unlocked it, which is the whole point of the shared runtime.
pub async fn unlock_vault(path: String, passphrase: String) -> Result<IdentityDto, UiError> {
    let mut guard = runtime().write().await;
    let identity = guard.unlock_vault(&path, &passphrase).await?;
    guard.spawn_event_loops();
    Ok(identity)
}

pub async fn is_vault_unlocked() -> bool {
    runtime().read().await.is_vault_unlocked()
}

pub async fn is_store_unlocked() -> bool {
    runtime().read().await.is_store_unlocked()
}

/// Re-lock the vault: abort the background feed/DM/sakha loops and drop the
/// store, engines, and in-memory identity.
pub async fn lock_vault() {
    runtime().write().await.lock_vault().await
}

